        children: "public final class GrpcServerModule implements AutoCloseable {\n\n    private final ExecutorService executor;\n    private final HealthStatusManager health;\n    private final Server server;\n\n    public GrpcServerModule(\n            GrpcServerConfig config,\n            CaseQueryGrpcService caseQueryService,\n            CaseCommandGrpcService caseCommandService,\n            TokenVerifier tokenVerifier\n    ) {\n        this.executor = Executors.newFixedThreadPool(config.executorThreads());\n        this.health = new HealthStatusManager();\n\n        NettyServerBuilder builder = NettyServerBuilder\n                .forPort(config.port())\n                .executor(executor)\n                .addService(caseQueryService)\n                .addService(caseCommandService)\n                .addService(health.getHealthService())\n                .intercept(new CorrelationIdServerInterceptor())\n                .intercept(new AuthenticationServerInterceptor(tokenVerifier))\n                .intercept(new GrpcServerLoggingInterceptor())\n                .maxInboundMessageSize(config.maxInboundMessageSize())\n                .maxInboundMetadataSize(config.maxInboundMetadataSize())\n                .permitKeepAliveTime(config.permitKeepAliveTimeSeconds(), TimeUnit.SECONDS)\n                .permitKeepAliveWithoutCalls(config.permitKeepAliveWithoutCalls());\n\n        if (config.reflectionEnabled()) {\n            builder.addService(ProtoReflectionService.newInstance());\n        }\n\n        this.server = builder.build();\n    }\n\n    public void start() throws IOException {\n        server.start();\n\n        health.setStatus(\n                \"\",\n                HealthCheckResponse.ServingStatus.SERVING\n        );\n    }\n\n    @Override\n    public void close() {\n        health.setStatus(\n                \"\",\n                HealthCheckResponse.ServingStatus.NOT_SERVING\n        );\n\n        server.shutdown();\n\n        try {\n            